import { parseCalendarDate } from '../utils/dateWindows.js';

/**
 * Derives supplier payables from an itinerary's day plan.
 *
 * The day plan (daysJson) already records which hotel and vehicle each day
 * uses and what they cost, so the money owed to each supplier can be rolled up
 * from it instead of being typed in twice. Auto-generated rows are marked with
 * autoGenerated so a regenerate can replace them without touching rows staff
 * entered by hand.
 */

const num = value => {
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
};

/** Per-night room charge for a day entry. */
const hotelCostForDay = day =>
  (num(day.basePrice) + num(day.roomTypePrice) + num(day.mealPlanPrice)) *
    Math.max(1, num(day.roomCount) || 1) +
  num(day.extraBedPrice) * num(day.extraBedCount) +
  num(day.childPrice) * num(day.childCount);

/** Per-day transport charge for a day entry. */
const vehicleCostForDay = day => num(day.ratePerDay) * Math.max(1, num(day.vehicleCount) || 1);

/** Normalise daysJson, which may arrive as a JSON string. */
const readDays = daysJson => {
  if (Array.isArray(daysJson)) return daysJson;
  if (typeof daysJson === 'string') {
    try {
      const parsed = JSON.parse(daysJson);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
};

/**
 * Roll a trip's day plan into one payable per supplier.
 * Returns plain objects; persisting them is the caller's job.
 */
export const derivePayables = itinerary => {
  const days = readDays(itinerary.daysJson);
  if (days.length === 0) return [];

  // key -> accumulated payable
  const buckets = new Map();

  const add = (key, seed, amount, serviceDate) => {
    if (amount <= 0) return;
    const existing = buckets.get(key);
    if (existing) {
      existing.amount += amount;
      // Supplier is paid by the first date their service is used.
      if (serviceDate && (!existing.dueDate || serviceDate < existing.dueDate)) {
        existing.dueDate = serviceDate;
      }
      return;
    }
    buckets.set(key, { ...seed, amount, dueDate: serviceDate || null });
  };

  for (const day of days) {
    const serviceDate = parseCalendarDate(day.date) || null;

    const hotelName = (day.hotelName || '').trim();
    if (hotelName) {
      add(
        `HOTEL:${day.hotelId || hotelName.toLowerCase()}`,
        {
          supplierType: 'HOTEL',
          supplierName: hotelName,
          supplierRefId: day.hotelId || null,
        },
        hotelCostForDay(day),
        serviceDate
      );
    }

    const vehicleName = (day.vehicleName || '').trim();
    if (vehicleName) {
      add(
        `VEHICLE:${day.vehicleId || vehicleName.toLowerCase()}`,
        {
          supplierType: 'VEHICLE',
          supplierName: vehicleName,
          supplierRefId: day.vehicleId || null,
        },
        vehicleCostForDay(day),
        serviceDate
      );
    }

    for (const activity of Array.isArray(day.activities) ? day.activities : []) {
      const activityName = (activity.name || activity.title || '').trim();
      const cost = num(activity.cost);
      if (!activityName || cost <= 0) continue;
      add(
        `ACTIVITY:${(activity.id || activityName).toString().toLowerCase()}`,
        {
          supplierType: 'ACTIVITY',
          supplierName: activityName,
          supplierRefId: activity.id || null,
        },
        cost,
        serviceDate
      );
    }
  }

  // Anything without a service date falls due on the trip start, else today.
  const fallbackDue =
    parseCalendarDate(itinerary.startDate) || parseCalendarDate(new Date()) || new Date();

  return [...buckets.values()].map(payable => ({
    ...payable,
    amount: Math.round(payable.amount * 100) / 100,
    dueDate: payable.dueDate || fallbackDue,
  }));
};
